import time
import random
from typing import Dict, Any, List, Optional

class MockUnstableAPI:
    def __init__(self):
        self.pages = {
            "cur_0": {"items": [{"id": 1}, {"id": 2}], "next_cursor": "cur_1"},
            "cur_1": {"items": [{"id": 3}, {"id": 4}], "next_cursor": "cur_2"},
            "cur_2": {"items": [{"id": 5}, {"id": 6}], "next_cursor": None}
        }

    def fetch_page(self, cursor: str) -> Dict[str, Any]:
        # Simular caidas de red aleatorias (40% probabilidad)
        if random.random() < 0.4:
            raise ConnectionResetError("503 Service Unavailable: Red inestable temporal")
        return self.pages[cursor]

def fetch_with_backoff(api: MockUnstableAPI, cursor: str, max_retries: int = 5) -> Dict[str, Any]:
    base_delay = 0.1
    for attempt in range(1, max_retries + 1):
        try:
            return api.fetch_page(cursor)
        except ConnectionResetError as e:
            if attempt == max_retries:
                raise RuntimeError(f"Fallo fatal tras {max_retries} reintentos: {e}")
            sleep_time = (base_delay * (2 ** (attempt - 1))) + random.uniform(0.01, 0.05)
            print(f"  [Fallo en cursor={cursor}] Reintento {attempt}/{max_retries} esperando {sleep_time:.2f}s...")
            time.sleep(sleep_time)
    raise RuntimeError("Error inesperado")

def run_extraction():
    api = MockUnstableAPI()
    cursor: Optional[str] = "cur_0"
    extracted_records = []

    print("Iniciando extraccion resiliente con paginacion por cursor...")
    while cursor is not None:
        response = fetch_with_backoff(api, cursor)
        items = response["items"]
        extracted_records.extend(items)
        print(f"-> Pagina extraida con exito: {len(items)} items. Siguiente cursor: {response['next_cursor']}")
        cursor = response["next_cursor"]

    print(f"\nExtraccion completada con exito. Total registros: {len(extracted_records)}")
    print(f"IDs recuperados: {[r['id'] for r in extracted_records]}")

run_extraction()
